from flask import Flask, render_template, request, redirect, url_for

app = Flask(__name__)

# In-memory storage for users (replace with database in production)
users = {}

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/sannu/<username>', methods=['GET', 'POST'])
def sannu(username):
    if request.method == 'POST':
        # Get the content from the form
        content = request.form.get('content', '')
        # Store the content for the user
        users[username] = content
        return redirect(url_for('sannu', username=username))

    # Retrieve the content for the user
    content = users.get(username, '')
    return render_template('sannu.html', username=username, content=content)

if __name__ == '__main__':
    app.run(debug=True)

